    if (r && r !== f) deps.add(r);
  }
  graph.set(f, [...deps]);
}
// 1-level cycles (A->B and B->A)
console.log('### One-level cycles (A imports B, B imports A):');
const pairs = new Set(); let found = 0;
for (const [a, deps] of graph) for (const b of deps) {
  if ((graph.get(b)||[]).includes(a)) {
    const k=[a,b].sort().join(' <-> ');
    if(!pairs.has(k)){pairs.add(k);console.log('  CYCLE: '+k);found++;}
  }
}
if(!found) console.log('  (none)');
// full DFS cycle detection
console.log('\n### Any-length cycles (DFS):');
const state = new Map(); const stack=[]; const cycles=new Set();
function dfs(n){
  state.set(n,1); stack.push(n);
  for (const d of graph.get(n)||[]) {
    if (state.get(d)===1) { const i=stack.indexOf(d); cycles.add(stack.slice(i).concat(d).join(' -> ')); }
    else if (!state.has(d)) dfs(d);
  }
  stack.pop(); state.set(n,2);
}
for (const f of graph.keys()) if(!state.has(f)) dfs(f);
console.log(cycles.size? [...cycles].join('\n') : '  (none)');
console.log('\n### Total files in overrides graph: '+files.length);
