import { breakpoints } from '../foundation/gridSystem';

// `tablet` mirrors the confirmed foundation token `breakpoints.md` — imported rather than
// retyped so the two cannot drift apart. `tabletWide` and `desktop` have no foundation
// equivalent yet; `desktop` additionally conflicts with Chakra's lg (62em) and xl (80em),
// which is why every desktop rule below is a raw @media rather than a responsive prop.
//
// theme/components/ otherwise avoids direct foundation/ imports in favour of --zimm-* CSS
// vars. Breakpoints are a deliberate exception: media queries cannot consume var().
// px ÷ 16; WCAG 1.4.4 requires em so queries shift with browser zoom.
const BP = {
  tablet: breakpoints.md, // Figma: alias/breakpoint/tablet — 768px
  tabletWide: '53.75em', // Figma: alias/breakpoint/tablet-wide — 860px (no foundation equivalent)
  desktop: '64em', // Figma: alias/breakpoint/desktop — 1024px (≠ Chakra lg=62em / xl=80em)
} as const;

// Provisional spacing/size values — kept here as named references until the UI designer
// confirms the token in foundation/spacing.ts or foundation/sizes.ts.
//
// SPACE_SECTION and SIZE_COL_NAV are NOT missing tokens: --zimm-scale-1200 (48px) and
// --zimm-scale-3500 (140px) already carry the same values. They are deliberately kept as
// rem here because those two foundation aliases are px, which does not scale under browser
// zoom (WCAG 1.4.4 — see overrideStyling.md Units). Collapse them onto the vars only once
// the foundation aliases move to rem.
const SPACE_SECTION = '3rem'; // alias/space/section (48px)
const SIZE_COL_NAV = '8.75rem'; // alias/size/footer/col-width-nav (140px)
const SIZE_COL_SUB = '20rem'; // alias/size/footer/col-width-subscribe (320px)
const SIZE_COL_MAP = '37.5rem'; // alias/size/footer/col-width-sitemap (600px)
const COLOUR_HALF_INV = 'rgba(255, 255, 255, 0.5)'; // alias/color/opacity-50-inverse
const SIZE_MODAL_SUB = '30rem'; // alias/size/modal/footer (480px)

