function resolveLocal(spec, from) {
  let base;
  if (spec.startsWith('.')) base = path.normalize(path.join(path.dirname(from), spec));
  else if (spec === 'app' || spec.startsWith('app/')) base = path.normalize(path.join('overrides/app', spec.slice(3)));
  else if (spec === '~' || spec.startsWith('~/')) base = path.normalize(spec.slice(2));
  else return 'external';
  for (const c of [base, ...exts.map(e=>base+e), ...exts.map(e=>path.join(base,'index'+e))]) {
    if (fs.existsSync(c) && fs.statSync(c).isFile()) return c;
  }
  return null;
}
